*, *::before, *::after {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  background: #f5f7fa;
  color: #1f2933;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
  min-height: 100vh;
}

.board {
  max-width: 720px;
  margin: 0 auto;
  padding: 20px 16px 40px;
}

h1 {
  font-size: 22px;
  font-weight: 600;
  margin: 0 0 16px;
  color: #102a43;
}

.task-form {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: flex-end;
  background: #ffffff;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 14px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.field span {
  font-size: 13px;
  color: #52606d;
}

.field input,
.field select {
  font: inherit;
  color: inherit;
  background: #ffffff;
  border: 1px solid #bcccdc;
  border-radius: 6px;
  padding: 8px 10px;
  min-height: 40px;
}

.field input {
  width: 100%;
}

.field:first-child {
  flex: 1 1 220px;
}

.field select {
  min-width: 96px;
}

.field input:focus,
.field select:focus,
button:focus-visible {
  outline: 2px solid #2f80ed;
  outline-offset: 1px;
}

button {
  font: inherit;
  cursor: pointer;
  border-radius: 6px;
  border: 1px solid #bcccdc;
  background: #ffffff;
  color: #1f2933;
  padding: 8px 14px;
  min-height: 40px;
}

button:hover {
  background: #f0f4f8;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

#add-button {
  background: #2f80ed;
  border-color: #2f80ed;
  color: #ffffff;
  font-weight: 600;
}

#add-button:hover {
  background: #1c6dd0;
}

.error {
  margin: 10px 0 0;
  padding: 8px 12px;
  background: #fdecea;
  border: 1px solid #f5c2c0;
  border-radius: 6px;
  color: #b42318;
  font-size: 14px;
  word-break: break-word;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin: 16px 0 12px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.filter {
  padding: 6px 12px;
  min-height: 36px;
  font-size: 14px;
}

.filter.active {
  background: #e3f0ff;
  border-color: #2f80ed;
  color: #1c6dd0;
  font-weight: 600;
}

.status {
  margin: 0;
  font-size: 13px;
  color: #52606d;
  min-height: 1.5em;
}

.status.is-error {
  color: #b42318;
}

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.task-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  background: #ffffff;
  border: 1px solid #d9e2ec;
  border-radius: 8px;
  padding: 10px 12px;
