  color: #b42318;
}

.priority-2 {
  background: #fff4e5;
  border-color: #f7d9a8;
  color: #8a5a00;
}

.priority-1 {
  background: #e8f5e9;
  border-color: #b7dfb9;
  color: #2e7d32;
}

.empty {
  margin: 16px 0 0;
  text-align: center;
  color: #829ab1;
  font-size: 14px;
}

@media (max-width: 480px) {
  .board {
    padding: 16px 12px 32px;
  }

  .task-form {
    padding: 12px;
  }

  .field:first-child {
    flex-basis: 100%;
  }

  #add-button {
    flex: 1 1 100%;
  }

  .toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
}
